// edet: `tauri android init` writes this file once and never again — it
// carries no AUTOGENERATED banner — which is why it is TRACKED (force-added
// past `src-tauri/.gitignore`, with `settings.gradle`, `app/build.gradle.kts`
// and the two plugin modules). Everything else under `gen/android` is
// regenerated.
//
// Two edits to the template, and both are load-bearing:
//
//   1. `enableEdgeToEdge()` before `super.onCreate`, so the WebView is laid
//      out under the system bars and the client's own layout decides the
//      padding.
//   2. **The WebView is re-resumed on pause while background mode is armed.**
//      `WryActivity.onPause()` — generated by wry on every build, never ours
//      to edit — calls `mWebView.onPause()`, whose contract is to pause the
//      WebView's "extra processing … DOM, plugins, JavaScript". The acceptance
//      rule IS that JavaScript (`ui/src/lib/autosign.ts` signs with the seed
//      held in the page), so a paused WebView is a wallet that has stopped
//      deciding the moment the member looked at something else. Resuming it
//      again here is the whole of what "keep deciding in the background"
//      means on Android; the foreground service beside it
//      (`AcceptanceService`) is what keeps the process alive to be resumed.
//
// The flag is the service's, not this file's: nothing here decides to keep
// running, it only carries out what the member turned on.
//
// **The system-bar insets are NOT published from here**, and the attempt is
// worth recording: `onWebViewCreate` runs before the page is loaded, so an
// `evaluateJavascript` from it lands in a document the real page then
// replaces — measured on a handset, where the custom properties read back
// EMPTY. The page pulls them instead, when it is ready to use them
// (`BackgroundPlugin.systemInsets`, `ui/src/lib/background.ts`).

package org.edet.client

import android.os.Bundle
import android.webkit.WebView
import androidx.activity.enableEdgeToEdge
import org.edet.client.background.BackgroundMode

class MainActivity : TauriActivity() {
  /** The one wry creates, handed to us by `WryActivity.setWebView`. */
  private var webView: WebView? = null

  override fun onCreate(savedInstanceState: Bundle?) {
    enableEdgeToEdge()
    super.onCreate(savedInstanceState)
  }

  override fun onWebViewCreate(webView: WebView) {
    super.onWebViewCreate(webView)
    this.webView = webView
  }

  override fun onPause() {
    // `super` is what pauses it; the order matters, and reversing it would
    // resume a WebView that is paused a line later.
    super.onPause()
    if (BackgroundMode.armed) {
      webView?.onResume()
    }
  }
}
